/* Browser-local integration: forecasts -> outcomes -> checked corrections -> tradeoff score. */
(function(root){
'use strict';
const C=root.FeelingCalibration,$=id=>document.getElementById(id),contexts={everyday:'Tasks / class / rest',purchase:'Purchases',relationship:'Relationships',income:'Income decisions'};
let enabled=true,incomeSnapshot=null,cache=new Map(),data=[];
try{enabled=JSON.parse(localStorage.getItem('worth-outcome-learning-v1')||'{}').enabled!==false;}catch{}
const panel=document.createElement('section');panel.className='card';panel.id='decisionLearning';panel.style.marginTop='32px';
panel.innerHTML='<p class="eyebrow">Personal learning · saved decisions and real outcomes</p><h2>Let your experience improve your next forecast.</h2><p>Save a comparison before choosing. In Your reflections, record which option you actually chose and how you felt soon afterward or at the saved later horizon. Only the chosen option provides an observed outcome.</p><label><input id="useDecisionLearning" type="checkbox" style="width:auto"> Use checked personal feeling estimates in my tradeoff scores</label><p id="decisionLearningStatus" role="status"></p><div id="decisionLearningEvidence" class="math-table"></div><details><summary>The feelings formula, research, and accuracy checks</summary><p class="formula">Learned feelings = clip(your forecast + β₀ + β₁ × (your forecast − 5)/5, 0, 10).<br>β = (XᵀX + 5I)⁻¹ Xᵀ(actual feelings − original forecasts), with X = [1, (forecast − 5)/5].</p><p>This is Bayesian/ridge forecast calibration: coefficients are shrunk toward zero correction when evidence is limited. It estimates your reported feelings on your saved scale. It is an experimental WAM adaptation, not a validated universal equation for emotions.</p><p>For each decision type, scale definition and time horizon, the app needs at least 10 usable outcomes and four chronological checks. Each check trains on at least six outcomes already recorded before that decision was saved. Corrections activate only when average absolute error improves on your original forecasts by more than 0.05 points. The latest 200 usable outcomes per group are used. Forecasts more than one point outside the observed forecast range stay unchanged. These sample sizes, ridge strength and thresholds are app settings, not scientific constants.</p><p>The feelings correction changes only selected feelings-now/later criteria. Separate resource learning can update time and effort estimates. Your importance weights, money inputs, other criteria, hard-limit values and relationship boundaries remain in control. The app shows the original and adjusted score. Similar histories do not reveal what an unchosen option would have caused. Error checks are descriptive and do not guarantee future accuracy or a confidence interval.</p><p>Research: <a href="https://dash.harvard.edu/entities/publication/d57b7409-6195-4481-9259-0bc1cf2aaea3" target="_blank" rel="noopener">Wilson &amp; Gilbert · affective forecasting</a>; <a href="https://online.stat.psu.edu/stat508/Lesson06.html" target="_blank" rel="noopener">Penn State · Bayesian interpretation of ridge shrinkage</a>. The separate reward-and-expectations experiment below uses <a href="https://www.pnas.org/doi/10.1073/pnas.1407535111" target="_blank" rel="noopener">Rutledge and colleagues’ momentary happiness model</a>.</p><p>Decision outcomes and original score snapshots stay on this device and are included in decision backups. Changing your scale definition or anchors starts a separate learning group. Old free-text notes and untimed ratings are not treated as verified numeric training examples; confirm and save an actual rating below to make it usable for future decisions.</p></details>';
$('learningLab').before(panel);const toggle=$('useDecisionLearning');toggle.checked=enabled;
function text(parent,tag,value){const node=document.createElement(tag);node.textContent=value;parent.append(node);return node;}
function rebuild(){data=C.observations(saved);cache=new Map();drawEvidence();}
function modelFor(scale,context,horizon){const key=JSON.stringify([scale,context,horizon]);if(!cache.has(key))cache.set(key,C.train(data.filter(r=>r.scale===scale&&r.context===context&&r.horizon===horizon)));return cache.get(key);}
function drawEvidence(){const scale=C.scaleKey(getPersonalProfile()),box=$('decisionLearningEvidence');box.replaceChildren();if(!scale){$('decisionLearningStatus').textContent='Define happiness and all three personal anchors above to learn on a consistent scale. Feeling estimates continue using your original forecasts.';return;}
 const rows=data.filter(r=>r.scale===scale),groups=new Map();rows.forEach(r=>groups.set(JSON.stringify([r.context,r.horizon]),r));$('decisionLearningStatus').textContent=`${rows.length} usable feeling rating${rows.length===1?'':'s'} from ${new Set(rows.map(r=>r.id.replace(/:(now|later)$/,''))).size} saved decisions on your current scale. `+(enabled?'Checked corrections apply automatically when there is evidence of improvement.':'Learning is switched off; original forecasts are used.');
 if(!rows.length){text(box,'p','No usable outcomes yet. Save a decision, then use “Record how it actually felt” in Your reflections.');return;}
 const table=document.createElement('table'),head=document.createElement('tr');for(const label of ['Decision type / horizon','Outcomes','Chronological checks','Average error · original → corrected','Status'])text(head,'th',label);table.append(head);
 for(const row of groups.values()){const m=modelFor(scale,row.context,row.horizon),tr=document.createElement('tr');for(const value of [contexts[row.context]+' · '+row.horizon,m.n,m.checked,m.mae===null?'Not enough later checks':m.originalMae.toFixed(2)+' → '+m.mae.toFixed(2)+' /10',m.ready?'Correction available':m.reason])text(tr,'td',String(value));table.append(tr);}box.append(table);const details=document.createElement('details');text(details,'summary','Fitted feeling-correction coefficients');for(const row of groups.values()){const m=modelFor(scale,row.context,row.horizon);if(m.beta)text(details,'p',contexts[row.context]+' · '+row.horizon+': β₀ = '+m.beta[0].toFixed(3)+', β₁ = '+m.beta[1].toFixed(3)+'. '+(m.ready?'Available for supported forecasts.':'Not applied until the accuracy check qualifies.'));}box.append(details);
}
function apply(input,context,horizon,income=false){if(input.factors.later?.weight>0&&!(typeof horizon==='string'&&horizon.trim()))throw Error('Name the later-feelings horizon before calculating.');const next=JSON.parse(JSON.stringify(input)),scale=C.scaleKey(getPersonalProfile()),changes=[];
 for(const slot of ['now','later']){const factor=next.factors[slot];if(!factor||factor.weight<=0)continue;for(const side of ['a','b']){const forecast=C.rating(factor[side]);if(forecast===null)continue;const key=C.horizonKey(slot,horizon),m=modelFor(scale,context,key),result=!enabled?{value:forecast,applied:false,reason:'Learning is switched off.'}:!scale?{value:forecast,applied:false,reason:'Define your personal scale first.'}:C.predict(m,forecast);factor[side]=result.value;changes.push({label:(income?(side==='b'?'New income option':'Current income option'):(side==='a'?'Main option':'Alternative'))+' · '+slot,original:forecast,value:result.value,applied:result.applied,reason:result.reason,n:m.n,checked:m.checked,mae:m.mae,originalMae:m.originalMae,coefficients:m.beta,forecastRange:[m.minForecast,m.maxForecast]});}}
 const applied=changes.some(c=>c.applied),summary=applied?'Personal learning adjusted selected feeling forecasts using comparable past outcomes. Unchecked forecasts remain your original estimates.':!enabled?'Personal learning is switched off. Original feeling forecasts are used.':!changes.length?'No feelings criteria are selected, so feeling calibration does not change this score.':!scale?'Feeling calibration: define your happiness scale and anchors to start learning. Original feeling forecasts are used.':'Feeling calibration is collecting comparable outcomes or checking accuracy. Original feeling forecasts are used until a correction qualifies.';
 return {input:next,summary,snapshot:{version:C.VERSION,enabled,scale,context,horizon,applied,changes}};
}
function processDecision(input){return apply(input,$('decisionType').value,$('scoreHorizon').value);}
function processIncome(input){return apply(input,'income',$('incomeFeelingHorizon').value,true);}
function refreshComparisons(){drawEvidence();if(current&&$('form').checkValidity()){addPerspective();renderNumbers();$('save').disabled=!current.decisionTradeoff;put('saveMessage','Learning updated this draft. Saved decisions keep their original score snapshots.');}if(incomeSnapshot&&$('tradeForm').checkValidity())$('tradeForm').requestSubmit();}
toggle.onchange=()=>{enabled=toggle.checked;try{localStorage.setItem('worth-outcome-learning-v1',JSON.stringify({enabled}));}catch{$('decisionLearningStatus').textContent='Preference applies for this session; browser storage is unavailable.';}refreshComparisons();};
const incomeSave=document.createElement('button');incomeSave.type='button';incomeSave.className='quiet';incomeSave.textContent='Save income decision & follow up';incomeSave.id='saveIncomeDecision';incomeSave.disabled=true;const incomeStatus=document.createElement('p');incomeStatus.id='incomeSaveStatus';incomeStatus.setAttribute('role','status');incomeStatus.className='helper';incomeStatus.textContent='Calculate a valid income score to save it. Optional feeling forecasts let later outcomes improve future feeling estimates.';$('tradeResult').after(incomeSave,incomeStatus);
function captureIncome(snapshot){incomeSnapshot=snapshot;incomeSave.disabled=false;incomeStatus.textContent='Ready to save this income comparison for follow-up.';}
for(const event of ['input','change'])$('tradeForm').addEventListener(event,()=>{incomeSnapshot=null;incomeSave.disabled=true;incomeStatus.textContent='Inputs changed. Recalculate before saving.';});
incomeSave.onclick=()=>{if(!incomeSnapshot||!$('tradeResult').querySelector('h3')){incomeSave.disabled=true;incomeStatus.textContent='Recalculate a valid score before saving.';return;}const s=incomeSnapshot,p=s.profile.factors,asRating=(slot,side)=>C.rating(p[slot]?.[side]),scale={...getPersonalProfile(),revision:personalRevision,horizon:$('incomeFeelingHorizon').value,scoreDoNow:asRating('now','b'),scoreAltNow:asRating('now','a'),scoreDoLater:asRating('later','b'),scoreAltLater:asRating('later','a')};const item={id:crypto.randomUUID(),date:new Date().toISOString(),decisionType:'income',task:('Choose new income option: $'+s.x.incomeB+'/year').slice(0,160),alt:('Keep current income option: $'+s.x.incomeA+'/year').slice(0,160),personalScale:scale,incomeTradeoff:s,decisionLearning:s.learning,profileSummary:$('tradeResult').textContent,next:''};saved.push(item);if(persist()){render();incomeSave.disabled=true;incomeStatus.textContent='Income decision saved. Record the chosen option and actual feelings in Your reflections.';}else{saved.pop();incomeStatus.textContent='Could not save in this browser.';}};
function decorateFollowups(){const items=saved.slice().reverse();Array.from($('entries').children).forEach((row,i)=>{const item=items[i],details=row.querySelector('details');if(!item?.personalScale||!details||details.querySelector('.feeling-followup'))return;
 const area=document.createElement('fieldset');area.className='feeling-followup';text(area,'legend','Record how it actually felt');const previous=item.feelingOutcomes,choice=document.createElement('select');choice.setAttribute('aria-label','Chosen option for '+item.task);[['','Choose an option…'],['do',item.task],['alt',item.alt]].forEach(([value,label])=>choice.add(new Option(label,value)));choice.value=item.outcomeChoice||previous?.choice||item.resourceOutcomes?.choice||item.actualChoice||'';text(area,'label','Which option did you actually choose?');area.append(choice);
 const inputs={};for(const slot of ['now','later']){const label=slot==='now'?'How did you feel soon afterward · 0–10 on the saved scale?':'How did you feel at '+(item.personalScale.horizon||'the saved later horizon')+' · 0–10?';const field=document.createElement('input');field.type='number';field.min=0;field.max=10;field.step='.5';field.setAttribute('aria-label',(slot==='now'?'Actual feelings soon after ':'Actual feelings later for ')+item.task);field.value=previous?.choice===choice.value?previous[slot]?.value??'':!previous&&(!item.actualChoice||item.actualChoice===choice.value)&&slot==='now'?item.actualScore??'':'';text(area,'label',label);area.append(field);inputs[slot]=field;}
 const label=document.createElement('label'),confirm=document.createElement('input');confirm.type='checkbox';confirm.style.width='auto';confirm.setAttribute('aria-label','Confirm feeling timing for '+item.task);label.append(confirm,document.createTextNode(' I am reporting the chosen option on its saved scale and at the timing labeled above. Leave the later rating blank until that horizon.'));area.append(label);const button=document.createElement('button');button.className='quiet';button.type='button';button.textContent='Save actual feelings';const status=document.createElement('p');status.className='helper';status.setAttribute('role','status');area.append(button,status);
 choice.onchange=()=>{const recordedChoice=item.outcomeChoice||item.feelingOutcomes?.choice||item.resourceOutcomes?.choice||item.actualChoice||'';if(recordedChoice&&choice.value!==recordedChoice){inputs.now.value='';inputs.later.value='';status.textContent='Choice changed. Enter outcomes for this choice; previous ratings will not be relabeled.';}confirm.checked=false;};
 button.onclick=()=>{if(!choice.value||!confirm.checked){status.textContent='Choose the option and confirm the scale and timing first.';return;}if(Object.values(inputs).some(field=>!field.checkValidity())){status.textContent='Use feelings ratings from 0 to 10 in steps of 0.5.';return;}if(!Object.values(inputs).some(field=>field.value!=='')){status.textContent='Enter at least one actual feelings rating.';return;}
 const original=item.feelingOutcomes,next={choice:choice.value},now=new Date().toISOString();for(const slot of ['now','later'])if(inputs[slot].value!==''){const value=Number(inputs[slot].value),old=original?.choice===choice.value?original[slot]:null;next[slot]=old&&old.value===value&&old.timingConfirmed===true&&Date.parse(old.recordedAt)>Date.parse(item.date)?old:{value,recordedAt:now,timingConfirmed:true};}
 const originalChoice=item.outcomeChoice,originalActual=item.actualChoice;item.feelingOutcomes=next;item.outcomeChoice=choice.value;item.actualChoice=choice.value;if(!persist()){item.feelingOutcomes=original;item.outcomeChoice=originalChoice;item.actualChoice=originalActual;status.textContent='Could not save; no new outcome was added.';return;}item.actualChoice=choice.value;status.textContent='Actual feelings saved. '+Object.entries(next).filter(([slot])=>slot!=='choice').map(([slot,outcome])=>{const forecast=C.rating(item.personalScale[(choice.value==='do'?'scoreDo':'scoreAlt')+(slot==='now'?'Now':'Later')]);return slot+': forecast '+(forecast===null?'not entered':forecast.toFixed(1))+'; actual '+outcome.value+'/10.';}).join(' ')+' Future comparisons use the updated checks.';document.dispatchEvent(new CustomEvent('wam:outcomes-updated',{detail:{id:item.id,choice:choice.value}}));rebuild();refreshComparisons();};
 details.append(area);});rebuild();}
root.WamDecisionLearning={processDecision,processIncome,captureIncome,decorateFollowups,refreshComparisons,outcomesChanged:()=>{rebuild();refreshComparisons();}};
document.addEventListener('wam:income-invalidated',()=>{incomeSnapshot=null;incomeSave.disabled=true;incomeStatus.textContent='Recalculate after changing priorities or limits.';});
document.addEventListener('wam:history-restored',()=>{rebuild();refreshComparisons();});
for(const id of ['scaleDefinition','anchorLow','anchorMid','anchorHigh']){$(id).addEventListener('change',drawEvidence);$(id).addEventListener('input',()=>{incomeSnapshot=null;incomeSave.disabled=true;incomeStatus.textContent='Scale changed. Recalculate the income comparison before saving.';});}$('savePersonal').addEventListener('click',drawEvidence);
decorateFollowups();
})(typeof globalThis!=='undefined'?globalThis:this);
